"use strict";(self.webpackChunklmcache_architecture_lectures=self.webpackChunklmcache_architecture_lectures||[]).push([["7928"],{691(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/lmcache-architecture-lectures/docs/roadmap","label":"\u{1F5FA}\uFE0F L\u1ED9 tr\xecnh & Syllabus","docId":"roadmap","unlisted":false},{"type":"link","href":"/lmcache-architecture-lectures/docs/lesson_0_kv_cache_sharing_fundamentals","label":"B\xe0i 0: T\u1ED5ng quan KV Cache Sharing","docId":"lesson_0_kv_cache_sharing_fundamentals","unlisted":false},{"type":"link","href":"/lmcache-architecture-lectures/docs/lesson_1_lmcache_architecture","label":"B\xe0i 1: Ki\u1EBFn tr\xfac LMCache","docId":"lesson_1_lmcache_architecture","unlisted":false},{"type":"link","href":"/lmcache-architecture-lectures/docs/lesson_2_hierarchical_storage","label":"B\xe0i 2: L\u01B0u tr\u1EEF ph\xe2n c\u1EA5p & Qu\u1EA3n l\xfd b\u1ED9 nh\u1EDB","docId":"lesson_2_hierarchical_storage","unlisted":false},{"type":"link","href":"/lmcache-architecture-lectures/docs/lesson_3_prefill_decode_disaggregation","label":"B\xe0i 3: Ph\xe2n t\xe1ch Prefill v\xe0 Decode","docId":"lesson_3_prefill_decode_disaggregation","unlisted":false},{"type":"link","href":"/lmcache-architecture-lectures/docs/lesson_4_vllm_sglang_integration","label":"B\xe0i 4: T\xedch h\u1EE3p vLLM v\xe0 SGLang","docId":"lesson_4_vllm_sglang_integration","unlisted":false},{"type":"category","label":"case_studies","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/lmcache-architecture-lectures/docs/case_studies/roadmap_case_studies","label":"\u{1F5FA}\uFE0F T\u1ED5ng quan Case Studies","docId":"case_studies/roadmap_case_studies","unlisted":false},{"type":"link","href":"/lmcache-architecture-lectures/docs/case_studies/case_0_chatbot_multi_round","label":"Case 0: Multi-round Chatbot","docId":"case_studies/case_0_chatbot_multi_round","unlisted":false},{"type":"link","href":"/lmcache-architecture-lectures/docs/case_studies/case_1_rag_at_scale","label":"Case 1: RAG at Scale","docId":"case_studies/case_1_rag_at_scale","unlisted":false},{"type":"link","href":"/lmcache-architecture-lectures/docs/case_studies/case_2_prefill_decode_disaggregation","label":"Case 2: PD Disaggregation","docId":"case_studies/case_2_prefill_decode_disaggregation","unlisted":false}]}]},"docs":{"case_studies/case_0_chatbot_multi_round":{"id":"case_studies/case_0_chatbot_multi_round","title":"Case Study 0: T\u1ED1i \u01B0u ho\xe1 H\u1EC7 th\u1ED1ng Chatbot H\u1ED9i tho\u1EA1i Nhi\u1EC1u l\u01B0\u1EE3t (Multi-round Chatbot)","description":"H\u1ED9i tho\u1EA1i nhi\u1EC1u l\u01B0\u1EE3t (multi-round conversation) l\xe0 m\u1ED9t trong nh\u1EEFng \u1EE9ng d\u1EE5ng ph\u1ED5 bi\u1EBFn nh\u1EA5t c\u1EE7a LLM. Tuy nhi\xean, vi\u1EC7c duy tr\xec l\u1ECBch s\u1EED h\u1ED9i tho\u1EA1i d\xe0i t\u1EA1o ra \xe1p l\u1EF1c r\u1EA5t l\u1EDBn l\xean h\u1EC7 th\u1ED1ng serving. Case study n\xe0y s\u1EBD ph\xe2n t\xedch c\xe1c \u0111i\u1EC3m ngh\u1EBDn c\u1ED5 chai ph\u1EA7n c\u1EE9ng v\xe0 c\xe1ch LMCache gi\xfap t\u1ED1i \u01B0u h\xf3a hi\u1EC7u n\u0103ng h\u1EC7 th\u1ED1ng chatbot.","sidebar":"tutorialSidebar"},"case_studies/case_1_rag_at_scale":{"id":"case_studies/case_1_rag_at_scale","title":"Case Study 1: T\u1ED1i \u01B0u ho\xe1 H\u1EC7 th\u1ED1ng RAG doanh nghi\u1EC7p Quy m\xf4 l\u1EDBn (RAG at Scale)","description":"H\u1EC7 th\u1ED1ng RAG (Retrieval-Augmented Generation) l\xe0 ki\u1EBFn tr\xfac c\u1ED1t l\xf5i gi\xfap k\u1EBFt n\u1ED1i LLM v\u1EDBi c\u01A1 s\u1EDF tri th\u1EE9c doanh nghi\u1EC7p. Khi s\u1ED1 l\u01B0\u1EE3ng t\xe0i li\u1EC7u v\xe0 ng\u01B0\u1EDDi d\xf9ng \u0111\u1ED3ng th\u1EDDi t\u0103ng l\xean, h\u1EC7 th\u1ED1ng \u0111\u1ED1i m\u1EB7t v\u1EDBi nh\u1EEFng gi\u1EDBi h\u1EA1n v\u1EADt l\xfd nghi\xeam tr\u1ECDng v\u1EC1 b\u0103ng th\xf4ng b\u1ED9 nh\u1EDB v\xe0 n\u0103ng l\u1EF1c prefill c\u1EE7a GPU. Case study n\xe0y ph\xe2n t\xedch c\xe1ch LMCache gi\xfap t\u0103ng v\u01B0\u1EE3t tr\u1ED9i th\xf4ng l\u01B0\u1EE3ng c\u1EE5m serving RAG.","sidebar":"tutorialSidebar"},"case_studies/case_2_prefill_decode_disaggregation":{"id":"case_studies/case_2_prefill_decode_disaggregation","title":"Case Study 2: Tri\u1EC3n khai ph\xe2n t\xe1ch Prefill-Decode (PD Disaggregation) trong C\u1EE5m Ph\u1EE5c v\u1EE5 Th\u01B0\u01A1ng m\u1EA1i","description":"Trong c\xe1c h\u1EC7 th\u1ED1ng API ph\u1EE5c v\u1EE5 LLM quy m\xf4 c\xf4ng nghi\u1EC7p (nh\u01B0 DeepSeek, OpenAI, ho\u1EB7c Anthropic), s\u1EF1 ch\xeanh l\u1EC7ch l\u1EDBn v\u1EC1 \u0111\u1ED9 tr\u1EC5 gi\u1EEFa pha Prefill v\xe0 Decode \u0111\xf2i h\u1ECFi m\u1ED9t gi\u1EA3i ph\xe1p ph\xe2n t\xe1ch t\xe0i nguy\xean tri\u1EC7t \u0111\u1EC3. Case study n\xe0y ph\xe2n t\xedch c\xe1ch tri\u1EC3n khai ph\xe2n t\xe1ch Prefill-Decode (PD Disaggregation) s\u1EED d\u1EE5ng k\xeanh truy\u1EC1n t\u1EA3i hi\u1EC7u n\u0103ng cao c\u1EE7a LMCache.","sidebar":"tutorialSidebar"},"case_studies/roadmap_case_studies":{"id":"case_studies/roadmap_case_studies","title":"LMCache Case Studies: \u1EE8ng d\u1EE5ng Th\u1EF1c t\u1EBF & T\u1ED1i \u01B0u H\u1EC7 th\u1ED1ng","description":"B\xean c\u1EA1nh vi\u1EC7c n\u1EAFm v\u1EEFng c\xe1c nguy\xean l\xfd ki\u1EBFn tr\xfac l\xfd thuy\u1EBFt, vi\u1EC7c hi\u1EC3u c\xe1ch \xe1p d\u1EE5ng LMCache v\xe0o c\xe1c t\xecnh hu\u1ED1ng th\u1EF1c t\u1EBF l\xe0 c\u1EF1c k\u1EF3 quan tr\u1ECDng \u0111\u1ED1i v\u1EDBi c\xe1c k\u1EF9 s\u01B0 v\u1EADn h\xe0nh h\u1EC7 th\u1ED1ng AI serving. Ph\u1EA7n n\xe0y cung c\u1EA5p 3 b\xe0i h\u1ECDc ph\xe2n t\xedch t\xecnh hu\u1ED1ng c\u1EE5 th\u1EC3 (case studies), m\xf4 t\u1EA3 c\xe1c v\u1EA5n \u0111\u1EC1 ngh\u1EBDn c\u1ED5 chai ph\u1EA7n c\u1EE9ng th\u1EF1c t\u1EBF v\xe0 c\xe1ch LMCache gi\xfap kh\u1EAFc ph\u1EE5c.","sidebar":"tutorialSidebar"},"lesson_0_kv_cache_sharing_fundamentals":{"id":"lesson_0_kv_cache_sharing_fundamentals","title":"B\xe0i 0: T\u1ED5ng quan v\u1EC1 Chia s\u1EBB KV Cache (KV Cache Sharing)","description":"Trong h\u1EC7 th\u1ED1ng ph\u1EE5c v\u1EE5 m\xf4 h\xecnh ng\xf4n ng\u1EEF l\u1EDBn (LLM Serving), KV Cache \u0111\xf3ng vai tr\xf2 quy\u1EBFt \u0111\u1ECBnh \u0111\u1ED1i v\u1EDBi hi\u1EC7u n\u0103ng h\u1EC7 th\u1ED1ng. Tuy nhi\xean, vi\u1EC7c qu\u1EA3n l\xfd v\xe0 chia s\u1EBB KV Cache hi\u1EC7u qu\u1EA3 v\u1EABn l\xe0 m\u1ED9t th\xe1ch th\u1EE9c l\u1EDBn. B\xe0i h\u1ECDc n\xe0y s\u1EBD ph\xe2n t\xedch b\u1EA3n ch\u1EA5t c\u1EE7a KV Cache, b\xe0i to\xe1n tr\xf9ng l\u1EB7p ti\u1EC1n t\u1ED1 (prefix reuse), v\xe0 t\u1EA1i sao ch\xfang ta c\u1EA7n m\u1ED9t gi\u1EA3i ph\xe1p chia s\u1EBB KV Cache ph\xe2n t\xe1n nh\u01B0 LMCache.","sidebar":"tutorialSidebar"},"lesson_1_lmcache_architecture":{"id":"lesson_1_lmcache_architecture","title":"B\xe0i 1: Chi ti\u1EBFt Ki\u1EBFn tr\xfac H\u1EC7 th\u1ED1ng LMCache","description":"\u0110\u1EC3 cung c\u1EA5p kh\u1EA3 n\u0103ng chia s\u1EBB KV Cache hi\u1EC7u n\u0103ng cao tr\xean quy m\xf4 c\u1EE5m m\xe1y ch\u1EE7, LMCache s\u1EED d\u1EE5ng thi\u1EBFt k\u1EBF ki\u1EBFn tr\xfac ph\xe2n t\u1EA7ng g\u1ED3m 3 l\u1EDBp ch\xednh: Frontend, Cache Engine, v\xe0 Storage Backend. B\xe0i h\u1ECDc n\xe0y s\u1EBD \u0111i s\xe2u ph\xe2n t\xedch s\u01A1 \u0111\u1ED3 ki\u1EBFn tr\xfac t\u1ED5ng quan v\xe0 ch\u1EE9c n\u0103ng c\u1EE7a t\u1EEBng l\u1EDBp trong m\xe3 ngu\u1ED3n LMCache.","sidebar":"tutorialSidebar"},"lesson_2_hierarchical_storage":{"id":"lesson_2_hierarchical_storage","title":"B\xe0i 2: C\u01A1 ch\u1EBF L\u01B0u tr\u1EEF Ph\xe2n c\u1EA5p v\xe0 Qu\u1EA3n l\xfd B\u1ED9 nh\u1EDB trong LMCache","description":"\u0110\u1EC3 t\u1ED1i \u01B0u h\xf3a chi ph\xed ph\u1EA7n c\u1EE9ng trong khi v\u1EABn \u0111\u1EA3m b\u1EA3o b\u0103ng th\xf4ng v\xe0 \u0111\u1ED9 tr\u1EC5 truy c\u1EADp t\u1ED1i thi\u1EC3u, LMCache thi\u1EBFt k\u1EBF c\u01A1 ch\u1EBF l\u01B0u tr\u1EEF ph\xe2n c\u1EA5p (Hierarchical Storage). B\xe0i h\u1ECDc n\xe0y s\u1EBD ph\xe2n t\xedch c\xe1c b\xe0i to\xe1n \u0111\xe1nh \u0111\u1ED5i v\u1EADt l\xfd, m\xf4 h\xecnh to\xe1n h\u1ECDc v\u1EC1 k\u1EF3 v\u1ECDng \u0111\u1ED9 tr\u1EC5, c\u1EA5u tr\xfac m\xe3 ngu\u1ED3n c\xe1c l\u1EDBp backend l\u01B0u tr\u1EEF, v\xe0 c\xe1ch hi\u1EC7n th\u1EF1c h\xf3a c\xe1c gi\u1EA3i thu\u1EADt gi\u1EA3i ph\xf3ng b\u1ED9 nh\u1EDB (cache eviction).","sidebar":"tutorialSidebar"},"lesson_3_prefill_decode_disaggregation":{"id":"lesson_3_prefill_decode_disaggregation","title":"B\xe0i 3: Gi\u1EA3i ph\xe1p Ph\xe2n t\xe1ch Prefill-Decode (PD Disaggregation)","description":"Trong c\xe1c h\u1EC7 th\u1ED1ng ph\u1EE5c v\u1EE5 m\xf4 h\xecnh ng\xf4n ng\u1EEF l\u1EDBn quy m\xf4 c\xf4ng nghi\u1EC7p, vi\u1EC7c \u0111\u1ED3ng \u0111\u1ECBa h\xf3a (colocation) hai giai \u0111o\u1EA1n Prefill v\xe0 Decode tr\xean c\xf9ng m\u1ED9t GPU t\u1EA1o ra s\u1EF1 tranh ch\u1EA5p t\xe0i nguy\xean v\xe0 l\xe0m t\u0103ng \u0111\xe1ng k\u1EC3 \u0111\u1ED9 tr\u1EC5. B\xe0i h\u1ECDc n\xe0y s\u1EBD ph\xe2n t\xedch chi ti\u1EBFt s\u1EF1 c\u0103ng th\u1EB3ng ph\u1EA7n c\u1EE9ng d\u1EABn \u0111\u1EBFn nhu c\u1EA7u ph\xe2n t\xe1ch Prefill-Decode (PD Disaggregation), x\xe2y d\u1EF1ng c\xf4ng th\u1EE9c gi\u1EDBi h\u1EA1n b\u0103ng th\xf4ng truy\u1EC1n t\u1EA3i, v\xe0 t\xecm hi\u1EC3u c\u01A1 ch\u1EBF ho\u1EA1t \u0111\u1ED9ng c\u1EE7a PDBackend trong LMCache.","sidebar":"tutorialSidebar"},"lesson_4_vllm_sglang_integration":{"id":"lesson_4_vllm_sglang_integration","title":"B\xe0i 4: T\xedch h\u1EE3p LMCache v\xe0o vLLM v\xe0 SGLang trong m\xf4i tr\u01B0\u1EDDng Multi-GPU","description":"Trong m\xf4i tr\u01B0\u1EDDng th\u1EF1c t\u1EBF, c\xe1c m\xf4 h\xecnh ng\xf4n ng\u1EEF l\u1EDBn th\u01B0\u1EDDng \u0111\u01B0\u1EE3c ch\u1EA1y tr\xean c\u1EA5u h\xecnh \u0111a GPU s\u1EED d\u1EE5ng c\u01A1 ch\u1EBF song song h\xf3a tensor (Tensor Parallelism - TP). Vi\u1EC7c t\xedch h\u1EE3p LMCache v\xe0o c\xe1c Serving Engine nh\u01B0 vLLM ho\u1EB7c SGLang \u0111\xf2i h\u1ECFi m\u1ED9t gi\u1EA3i ph\xe1p \u0111i\u1EC1u ph\u1ED1i \u0111a ti\u1EBFn tr\xecnh th\xf4ng minh \u0111\u1EC3 tr\xe1nh overhead b\u0103ng th\xf4ng PCIe. B\xe0i h\u1ECDc n\xe0y s\u1EBD ph\xe2n t\xedch c\xe1c th\xe1ch th\u1EE9c \u0111a ti\u1EBFn tr\xecnh, m\xf4 h\xecnh to\xe1n h\u1ECDc v\u1EC1 b\u0103ng th\xf4ng PCIe, c\u1EA5u tr\xfac m\xe3 ngu\u1ED3n c\xe1c adapter t\xedch h\u1EE3p, v\xe0 quy tr\xecnh c\u1EA5u h\xecnh h\u1EC7 th\u1ED1ng.","sidebar":"tutorialSidebar"},"roadmap":{"id":"roadmap","title":"LMCache Internals: Deep Dive into KV Cache Sharing Architecture","description":"Ch\xe0o m\u1EEBng b\u1EA1n \u0111\u1EBFn v\u1EDBi kho l\u01B0u tr\u1EEF b\xe0i gi\u1EA3ng LMCache Internals: Deep Dive into KV Cache Sharing Architecture. Chu\u1ED7i b\xe0i gi\u1EA3ng n\xe0y \u0111\u01B0\u1EE3c thi\u1EBFt k\u1EBF \u0111\u1EB7c bi\u1EC7t cho c\xe1c AI Serving Engineer, Deep Learning Engineer v\xe0 Systems Architect mu\u1ED1n t\xecm hi\u1EC3u s\xe2u s\u1EAFc v\u1EC1 c\xe1ch t\u1ED1i \u01B0u h\xf3a LLM serving b\u1EB1ng c\u01A1 ch\u1EBF chia s\u1EBB, l\u01B0u tr\u1EEF v\xe0 offload Key-Value (KV) Cache gi\u1EEFa nhi\u1EC1u ti\u1EBFn tr\xecnh v\xe0 GPU kh\xe1c nhau qua th\u01B0 vi\u1EC7n LMCache.","sidebar":"tutorialSidebar"}}}}')}}]);